<?php defined('ABSPATH')||exit; function bluprint_editorial_defaults(){ return [ 'enabled'=>1, 'eyebrow'=>'اینجا نقطه شروع توست', 'title'=>"هنوز ساخته نشده.\nمنتظر دست‌های توست.", 'description'=>'یک صفحه سفید، یک مداد و هزار امکان. بلوپرینت برای لحظه‌ای است که تصمیم می‌گیری ایده‌ات را از ذهنت بیرون بیاوری؛ چه اولین اسکیس تو باشد، چه پروژه بعدی‌ات.', 'button_text'=>'ابزار ایده‌ام را پیدا کنم', 'button_url'=>'', 'button_target'=>0, 'image_id'=>0, 'image_alt'=>'', 'shadow_color'=>'#093FB9' ]; }
function bluprint_editorial_sanitize($value){ $defaults=bluprint_editorial_defaults(); $value=is_array($value)?$value:[]; $shadow=sanitize_hex_color($value['shadow_color']??$defaults['shadow_color']); return [ 'enabled'=>!empty($value['enabled'])?1:0, 'eyebrow'=>sanitize_text_field($value['eyebrow']??$defaults['eyebrow']), 'title'=>sanitize_textarea_field($value['title']??$defaults['title']), 'description'=>sanitize_textarea_field($value['description']??$defaults['description']), 'button_text'=>sanitize_text_field($value['button_text']??$defaults['button_text']), 'button_url'=>esc_url_raw($value['button_url']??''), 'button_target'=>!empty($value['button_target'])?1:0, 'image_id'=>absint($value['image_id']??0), 'image_alt'=>sanitize_text_field($value['image_alt']??''), 'shadow_color'=>$shadow?:$defaults['shadow_color'] ]; }
function bluprint_editorial_register(){ register_setting('bluprint_editorial_group','bluprint_editorial_section',[ 'type'=>'array', 'sanitize_callback'=>'bluprint_editorial_sanitize', 'default'=>bluprint_editorial_defaults() ]); add_submenu_page('bluprint-settings','سکشن معرفی','سکشن معرفی','manage_options','bluprint-editorial','bluprint_editorial_admin'); }
add_action('admin_menu','bluprint_editorial_register'); function bluprint_editorial_admin(){ if(!current_user_can('manage_options'))return; $data=wp_parse_args(get_option('bluprint_editorial_section',[]),bluprint_editorial_defaults()); $image=$data['image_id']?wp_get_attachment_image_url($data['image_id'],'medium'):''; ?> <div class="wrap"> <h1>سکشن معرفی صفحه اصلی</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_editorial_group'); ?> <table class="form-table"> <tr><th>وضعیت سکشن</th><td><label><input type="checkbox" name="bluprint_editorial_section[enabled]" value="1" <?php checked($data['enabled'],1); ?>> نمایش سکشن در صفحه اصلی</label></td></tr> <tr><th><label for="bp-editorial-eyebrow">عنوان بالایی</label></th><td><input id="bp-editorial-eyebrow" class="large-text" name="bluprint_editorial_section[eyebrow]" value="<?php echo esc_attr($data['eyebrow']); ?>"></td></tr> <tr><th><label for="bp-editorial-title">عنوان اصلی</label></th><td><textarea id="bp-editorial-title" class="large-text" rows="3" name="bluprint_editorial_section[title]"><?php echo esc_textarea($data['title']); ?></textarea><p class="description">برای شکستن عنوان به چند خط از Enter استفاده کن.</p></td></tr> <tr><th><label for="bp-editorial-description">توضیحات</label></th><td><textarea id="bp-editorial-description" class="large-text" rows="4" name="bluprint_editorial_section[description]"><?php echo esc_textarea($data['description']); ?></textarea></td></tr> <tr><th><label for="bp-editorial-button">متن دکمه</label></th><td><input id="bp-editorial-button" class="regular-text" name="bluprint_editorial_section[button_text]" value="<?php echo esc_attr($data['button_text']); ?>"></td></tr> <tr><th><label for="bp-editorial-url">لینک دکمه</label></th><td><input type="url" id="bp-editorial-url" class="large-text" name="bluprint_editorial_section[button_url]" value="<?php echo esc_attr($data['button_url']); ?>"></td></tr> <tr><th>نحوه باز شدن لینک</th><td><label><input type="checkbox" name="bluprint_editorial_section[button_target]" value="1" <?php checked($data['button_target'],1); ?>> باز شدن در تب جدید</label></td></tr> <tr> <th><label for="bp-editorial-shadow-color">رنگ سایه تصویر</label></th> <td> <input type="text" id="bp-editorial-shadow-color" class="bp-editorial-color-picker" name="bluprint_editorial_section[shadow_color]" value="<?php echo esc_attr($data['shadow_color']); ?>" data-default-color="#093FB9"> <p class="description">رنگ سایه پشت تصویر را انتخاب کن.</p> </td> </tr> <tr> <th>تصویر سکشن</th> <td> <input type="hidden" id="bp-editorial-image-id" name="bluprint_editorial_section[image_id]" value="<?php echo esc_attr($data['image_id']); ?>"> <div id="bp-editorial-image-preview"> <?php if($image): ?><img src="<?php echo esc_url($image); ?>" style="max-width:320px;height:auto;display:block;margin-bottom:12px"><?php endif; ?> </div> <button type="button" class="button" id="bp-editorial-image-select">انتخاب تصویر</button> <button type="button" class="button" id="bp-editorial-image-remove">حذف تصویر انتخاب‌شده</button> <p class="description">در صورت انتخاب نکردن تصویر، تصویر پیش‌فرض قالب نمایش داده می‌شود.</p> </td> </tr> <tr><th><label for="bp-editorial-alt">متن جایگزین تصویر</label></th><td><input id="bp-editorial-alt" class="large-text" name="bluprint_editorial_section[image_alt]" value="<?php echo esc_attr($data['image_alt']); ?>"></td></tr> </table> <?php submit_button('ذخیره تغییرات'); ?> </form> </div> <?php }
function bluprint_editorial_admin_assets($hook){ if(!bluprint_is_admin_page('bluprint-editorial'))return; wp_enqueue_media(); wp_enqueue_style('wp-color-picker'); wp_enqueue_script('wp-color-picker'); wp_enqueue_script('jquery'); wp_add_inline_script('wp-color-picker'," jQuery(function($){ $('.bp-editorial-color-picker').wpColorPicker(); let frame; $('#bp-editorial-image-select').on('click',function(e){ e.preventDefault(); if(frame){frame.open();return;} frame=wp.media({title:'انتخاب تصویر سکشن',button:{text:'استفاده از تصویر'},multiple:false,library:{type:'image'}}); frame.on('select',function(){ const image=frame.state().get('selection').first().toJSON(); $('#bp-editorial-image-id').val(image.id); $('#bp-editorial-image-preview').empty().append($('<img>',{src:image.url,css:{maxWidth:'320px',height:'auto',display:'block',marginBottom:'12px'}})); }); frame.open(); }); $('#bp-editorial-image-remove').on('click',function(){ $('#bp-editorial-image-id').val('0'); $('#bp-editorial-image-preview').empty(); }); }); "); }
add_action('admin_enqueue_scripts','bluprint_editorial_admin_assets'); function bluprint_get_editorial_data(){ return wp_parse_args(get_option('bluprint_editorial_section',[]),bluprint_editorial_defaults()); }